?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KaMi Wedding Admin</title><link rel="icon" type="image/svg+xml" href="/favicon.svg"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><style>:root{--k:#514332;--bg:#f5f2ec}body{background:var(--bg);color:#29251f}.sidebar{width:250px;background:#2f2923;min-height:100vh}.sidebar .nav-link{color:#d8d0c7;border-radius:12px;margin:3px 0}.sidebar .nav-link.active,.sidebar .nav-link:hover{background:#51473b;color:#fff}.brand{color:#fff;font-weight:800;font-size:21px}.card{border:1px solid #e5ddd2;border-radius:18px}.btn-kami{background:var(--k);color:#fff}.btn-kami:hover{background:#403428;color:#fff}.icon-btn{width:42px;height:42px;padding:0;display:inline-flex;align-items:center;justify-content:center;font-size:18px}.badge-soft{background:#e2f2e7;color:#247042}.badge-pending{background:#eee9e1;color:#766b60}.logout-link{display:flex;align-items:center;gap:10px;color:#d8d0c7;text-decoration:none;padding:10px 14px;border-radius:12px;margin-top:auto;transition:all .2s ease}.logout-link:hover{background:rgba(220,53,69,.12);color:#ff6b78}.logout-link i{font-size:18px}.blast-check{width:20px;height:20px;cursor:pointer}@media(max-width:768px){.sidebar{width:72px}.brand-text,.nav-text,.logout-text{display:none}.sidebar .nav-link{justify-content:center}.logout-link{justify-content:center;padding:10px 0}.content{width:calc(100% - 72px)}} </style></head><body><div class="d-flex"><aside class="sidebar p-3 d-flex flex-column flex-shrink-0"><div class="brand px-2 py-2 mb-4"><i class="bi bi-heart-fill me-2"></i><span class="brand-text">KaMi Wedding</span></div><nav class="nav nav-pills flex-column"><a class="nav-link <?=active('dashboard',$page)?>" href="dashboard.php?page=dashboard"><i class="bi bi-grid me-md-2"></i><span class="nav-text">Dashboard</span></a><a class="nav-link <?=active('guests',$page)?>" href="dashboard.php?page=guests"><i class="bi bi-people me-md-2"></i><span class="nav-text">Data Tamu</span></a><?php if(isKhaikal()):?><a class="nav-link <?=active('config',$page)?>" href="dashboard.php?page=config"><i class="bi bi-gear me-md-2"></i><span class="nav-text">Config</span></a><?php endif;?></nav><a class="logout-link" href="logout.php"><i class="bi bi-box-arrow-right"></i><span class="logout-text">Logout</span></a></aside><main class="content flex-grow-1"><div class="container-fluid p-3 p-md-4 p-lg-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 fw-bold mb-1"><?=e($page==='guests'?'Data Tamu':($page==='config'?'Config':'Dashboard'))?></h1><div class="text-secondary">KaMi Wedding Invitation</div></div><div class="badge text-bg-light border p-2"><i class="bi bi-person-fill me-1"></i><?=e(USERS[currentUser()]['label'])?></div></div><?php if($flash):?><div class="alert alert-<?=$flash[0]?>"><?=e($flash[1])?></div><?php endif;?><?php if($page==='dashboard'):?><div class="row g-3"><div class="col-md-4"><div class="card p-4"><div class="text-secondary">Total Tamu</div><div class="display-6 fw-bold"><?=$total?></div></div></div><div class="col-md-4"><div class="card p-4"><div class="text-secondary">Terkirim</div><div class="display-6 fw-bold"><?=$sent?></div></div></div><div class="col-md-4"><div class="card p-4"><div class="text-secondary">Belum Terkirim</div><div class="display-6 fw-bold"><?=$total-$sent?></div></div></div></div><div class="card p-4 mt-3"><h5>Selamat datang, <?=e(USERS[currentUser()]['label'])?> 👋</h5><p class="text-secondary mb-0">Kelola daftar tamu dan kirim undangan WhatsApp.</p></div><?php elseif($page==='guests'):?><div class="d-flex flex-column flex-md-row justify-content-between gap-2 mb-3"><div class="d-flex gap-2 flex-grow-1"><input id="search" class="form-control" placeholder=