$g['id'])?>"><i class="bi bi-pencil"></i></a><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="send_wa"><input type="hidden" name="id" value="<?=e($g['id'])?>"><button class="btn btn-kami icon-btn" type="submit" title="Kirim WhatsApp"><i class="bi bi-whatsapp"></i></button></form><button class="btn btn-light border icon-btn copy-message-btn" type="button" title="Salin Pesan" data-message="<?=e($copyMsg)?>"><i class="bi bi-copy"></i></button><form method="post" onsubmit="return confirm('Hapus data tamu ini?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete_guest"><input type="hidden" name="id" value="<?=e($g['id'])?>"><button class="btn btn-outline-danger icon-btn" type="submit" title="Delete"><i class="bi bi-trash3"></i></button></form></div></td></tr><?php endforeach;?><?php if(!$guests):?><tr><td colspan="5" class="text-center text-secondary py-5">Belum ada data tamu.</td></tr><?php endif;?></tbody></table></div></div><?php elseif($page==='config'):?><div class="card p-4"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="save_config"><div class="mb-3"><label class="form-label fw-semibold">Link Undangan</label><input class="form-control" name="invite_link" value="<?=e($cfg['invite_link'])?>"></div><div class="mb-3"><label class="form-label fw-semibold">Template WhatsApp</label><textarea class="form-control" name="whatsapp_template" rows="18"><?=e($cfg['whatsapp_template'])?></textarea></div><button class="btn btn-kami">Simpan Config</button></form></div><?php endif;?><?php if($page==='guests'&&isset($_GET['edit'])):$new=$edit==='new';?><div class="modal fade show d-block" style="background:#0006"><div class="modal-dialog modal-dialog-centered"><div class="modal-content rounded-4"><form method="post"><div class="modal-header"><h5 class="modal-title"><?=$new?'Tambah Data':'Edit Data'?></h5><a href="dashboard.php?page=guests" class="btn-close"></a></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="save_guest"><input type="hidden" name="id" value="<?=$new?'':e($eg['id']??'')?>"><div class="mb-3"><label class="form-label">Nama</label><input class="form-control" name="name" value="<?=e($new?'':($eg['name']??''))?>" required autofocus></div><div><label class="form-label">Phone</label><input class="form-control" name="phone" value="<?=e($new?'':($eg['phone']??''))?>" placeholder="08123456789" required></div></div><div class="modal-footer"><a class="btn btn-light" href="dashboard.php?page=guests">Batal</a><button class="btn btn-kami">Simpan</button></div></form></div></div></div><?php endif;?></div></main></div><div class="modal fade" id="copyModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content rounded-4"><div class="modal-header"><h5 class="modal-title">Pesan Undangan</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><textarea id="copyText" class="form-control" rows="14" readonly></textarea></div><div class="modal-footer"><button type="button" class="btn btn-kami" id="copyNow"><i class="bi bi-copy me-1"></i> Salin Pesan</button></div></div></div></div><div class="modal fade" id="blastModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content rounded-4"><div class="modal-header"><h5 class="modal-title"><i class="bi bi-whatsapp me-2"></i>Blast WhatsApp</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="mb-2 d-flex justify-content-between"><span class="text-secondary">Progress</span><strong id="blastProgressText">0 / 0</strong></div><div class="progress mb-3" style="height:10px"><div id="blastProgress" class="progress-bar" style="width:0%"></div></div><div class="card p-3"><div class="small text-secondary mb-1">Tamu saat ini</div><div id="blastGuestName" class="fw-bold">-</div><div id="blastGuestPhone" class="text-secondary small">-</div></div><div class="alert alert-info mt-3 mb-0 small"><i class="bi bi-info-circle me-1"></i>WhatsApp akan dibuka untuk satu tamu. Klik <b>Kirim</b> di WhatsApp, lalu kembali ke sini dan tekan <b>Terkirim & Berikutnya</b>.</div></div><div class="modal-footer"><button type="button" class="btn btn-light" id="blastClose" data-bs-dismiss="modal">Tutup</button><button type="button" class="btn btn-outline-secondary" id="blastOpen"><i class="bi bi-whatsapp me-1"></i>Buka WhatsApp</button><button type="button" class="btn btn-kami" id="blastNext"><i class="bi bi-check-lg me-1"></i>Terkirim & Berikutnya</button></div></div></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>const s=document.getElementById('search');if(s)s.oninput=()=>{let q=s.value.toLowerCase();document.querySelectorAll('#guestTable tbody tr').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(q)?'':'none')};let selectedMessage='';const copyModalEl=document.getElementById('copyModal');const copyModal=copyModalEl?new bootstrap.Modal(copyModalEl):null;document.querySelectorAll('.copy-message-btn').forEach(btn=>btn.addEventListener('click',()=>{selectedMessage=btn.dataset.message||'';document.getElementById('copyText').value=selectedMessage;if(copyModal)copyModal.show()}));document.getElementById('copyNow')?.addEventListener('click',async()=>{const ta=document.getElementById('copyText');ta.focus();ta.select();try{await navigator.clipboard.writeText(selectedMessage);alert('Pesan berhasil disalin.')}catch(e){try{document.execCommand('copy');alert('Pesan berhasil disalin.')}catch(e2){alert('Silakan tekan Ctrl+C untuk menyalin pesan.')}}});
const csrf='<?=e(csrf())?>';const checks=()=>Array.from(document.querySelectorAll('.guest-check:checked'));const updateSelected=()=>{const n=checks().length;const c=document.getElementById('selectedCount');if(c)c.textContent=n;const all=document.querySelectorAll('.guest-check');const h=document.getElementById('headerCheck');if(h)h.checked=all.length>0&&n===all.length;};document.getElementById('headerCheck')?.addEventListener('change',e=>{document.querySelectorAll('.guest-check').forEach(c=>c.checked=e.target.checked);updateSelected()});document.getElementById('selectAllBtn')?.addEventListener('click',()=>{const all=document.querySelectorAll('.guest-check');const should=Array.from(all).some(c=>!c.checked);all.forEach(c=>c.checked=should);updateSelected()});document.querySelectorAll('.guest-check').forEach(c=>c.addEventListener('change',updateSelected));
let blastQueue=[],blastIndex=0;const blastModalEl=document.getElementById('blastModal');const blastModal=blastModalEl?new bootstrap.Modal(blastModalEl,{backdrop:'static'}):null;function renderBlast(){const g=blastQueue[blastIndex];if(!g)return;document.getElementById('blastGuestName').textContent=g.name;document.getElementById('blastGuestPhone').textContent=g.phone;document.getElementById('blastProgressText').textContent=(blastIndex+1)+' / '+blastQueue.length;document.getElementById('blastProgress').style.width=((blastIndex)/blastQueue.length*100)+'%';}function openCurrent(){const g=blastQueue[blastIndex];if(g)window.open(g.waUrl,'_blank','noopener,noreferrer');}async function markSent(id){const fd=new FormData();fd.append('csrf',csrf);fd.append('action','mark_sent');fd.append('id',id);const r=await fetch('dashboard.php?page=guests',{method:'POST',body:fd});return r.ok;}document.getElementById('blastBtn')?.addEventListener('click',()=>{const rows=checks().map(c=>c.closest('tr'));if(!rows.length){alert('Pilih minimal 1 tamu.');return;}blastQueue=rows.map(r=>({id:r.dataset.guestId,name:r.dataset.name,phone:r.dataset.phone,waUrl:r.dataset.waUrl}));blastIndex=0;renderBlast();blastModal?.show()});document.getElementById('blastOpen')?.addEventListener('click',openCurrent);document.getElementById('blastNext')?.addEventListener('click',async()=>{const g=blastQueue[blastIndex];if(!g)return;const ok=await markSent(g.id);if(!ok){alert('Gagal memperbarui status tamu.');return;}const row=document.querySelector('tr[data-guest-id="'+CSS.escape(g.id)+'"]');if(row){const badge=row.querySelector('td:nth-child(4) span');if(badge){badge.textContent='Terkirim';badge.className='badge rounded-pill badge-soft';}}blastIndex++;if(blastIndex>=blastQueue.length){document.getElementById('blastProgressText').textContent=blastQueue.length+' / '+blastQueue.length;document.getElementById('blastProgress').style.width='100%';document.getElementById('blastGuestName').textContent='Selesai 🎉';document.getElementById('blastGuestPhone').textContent='Semua tamu yang dipilih sudah diproses.';document.getElementById('blastOpen').disabled=true;document.getElementById('blastNext').disabled=true;return;}renderBlast();openCurrent()});</script></body></html>